entries[268914] = { ["name"] = "Unbeirrbare Navigation", ["text"] = "Wirken in 2 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nUmbralsplitter (6), Düsterstaub (18), Trüber Kristall\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Rüstung 30 Sek. lang um 15 erhöht wird. Dieser Effekt ist bis zu 5-mal stapelbar. Beim Erreichen von 5 Stapeln werden alle Stapel verbraucht und Eure Rüstung wird 10 Sek. lang um 179 erhöht.\n\nMaterialbedarf verringert.\nBeruf:\nVerzauberkunst von Battle for Azeroth (125)\nLehrer:\nVerzauberin Quinni\nZone:\nZuldazar\nKosten:\n25" }
